"""Underline all headline (all-caps section title) paragraphs in quarterly_report."""
import xml.etree.ElementTree as ET

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XMLNS = "http://www.w3.org/XML/1998/namespace"


def q(tag):
    return "{%s}%s" % (W, tag)


ET.register_namespace("w", W)
ET.register_namespace("xml", XMLNS)

path = "unpacked/word/document.xml"
tree = ET.parse(path)
root = tree.getroot()
body = root.find(q("body"))


def para_text(p):
    return "".join(t.text or "" for t in p.iter(q("t")))


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    if not any(ch.isalpha() for ch in s):
        return False
    # All-caps short section titles have no lowercase characters
    if any(ch.islower() for ch in s):
        return False
    return True


# Elements that must follow <w:u> inside <w:rPr> per the OOXML schema
AFTER_U = {"effect", "bdr", "shd", "fitText", "vertAlign", "rtl",
           "cs", "em", "lang", "eastAsianLayout", "specVanish", "oMath"}


def ensure_underline(r):
    rpr = r.find(q("rPr"))
    if rpr is None:
        rpr = ET.Element(q("rPr"))
        r.insert(0, rpr)  # w:rPr must be the first child of w:r
    if rpr.find(q("u")) is not None:
        return False
    u = ET.Element(q("u"), {q("val"): "single"})
    children = list(rpr)
    idx = len(children)
    for i, ch in enumerate(children):
        if ch.tag.rsplit("}", 1)[-1] in AFTER_U:
            idx = i
            break
    rpr.insert(idx, u)
    return True


headlines = []
for p in body.findall(q("p")):
    text = para_text(p)
    if not is_headline(text):
        continue
    n = 0
    for r in p.iter(q("r")):
        if r.find(q("t")) is None and r.find(q("delText")) is None:
            continue  # runs without text content (e.g., empty spacing runs)
        if ensure_underline(r):
            n += 1
    headlines.append((text.strip(), n))

tree.write(path, encoding="utf-8", xml_declaration=True)

print("Headline paragraphs underlined:")
for text, n in headlines:
    print("  [%d run(s)] %s" % (n, text))
print("Total: %d headline paragraphs" % len(headlines))

import sys
import xml.etree.ElementTree as ET

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
def q(name):
    return '{%s}%s' % (W, name)

path = sys.argv[1] if len(sys.argv) > 1 else 'unpacked/word/document.xml'

ET.register_namespace('w', W)

tree = ET.parse(path)
root = tree.getroot()
body = root.find(q('body'))

def paragraph_text(p):
    parts = []
    for r in p.iter(q('r')):
        for t in r.iter(q('t')):
            parts.append(t.text or '')
    return ''.join(parts)

def looks_like_headline(text):
    s = text.strip()
    if not s:
        return False
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return False
    return all(c.isupper() for c in letters)

headline_texts = []
for p in body.findall(q('p')):
    text = paragraph_text(p)
    if not looks_like_headline(text):
        continue
    headline_texts.append(text.strip())
    for r in p.findall(q('r')):
        rpr = r.find(q('rPr'))
        if rpr is None:
            rpr = ET.Element(q('rPr'))
            r.insert(0, rpr)
        if rpr.find(q('u')) is None:
            u = ET.SubElement(rpr, q('u'))
            u.set(q('val'), 'single')

tree.write(path, encoding='ascii', xml_declaration=True)

# verification pass: re-read and confirm each headline paragraph's runs carry the underline
tree2 = ET.parse(path)
body2 = tree2.getroot().find(q('body'))
verified = []
for p in body2.findall(q('p')):
    if not looks_like_headline(paragraph_text(p)):
        continue
    runs = p.findall(q('r'))
    ok = len(runs) > 0 and all(
        (r.find(q('rPr')) is not None and r.find(q('rPr')).find(q('u')) is not None
         and r.find(q('rPr')).find(q('u')).get(q('val')) == 'single')
        for r in runs
    )
    verified.append(paragraph_text(p).strip() if ok else None)

print('headlines underlined: %d' % len(headline_texts))
for t in headline_texts:
    print(' - %s' % t)
if None in verified or len(verified) != len(headline_texts):
    sys.exit(1)
print('verification: all headline paragraphs confirmed underlined')

